const out = [];
for (const el of document.querySelectorAll('*')) {
  const cs = getComputedStyle(el);
  if (cs.cursor !== 'pointer' || cs.display === 'none') continue;
  const r = el.getBoundingClientRect();
  if (r.width < 80 || r.height < 80 || r.x < 316 || r.x > 1100) continue;
  const txt = (el.textContent || '').trim().slice(0, 40);
  if (txt) out.push({t: txt, x: Math.round(r.x + r.width/2), y: Math.round(r.y + r.height/2)});
}
return JSON.stringify(out);

// Inspect right sidebar contents
const right = document.querySelector('.right-ui-bar, [class*=right]');
if (!right) return JSON.stringify({err: 'no right sidebar found'});
return JSON.stringify({
  innerText: right.innerText.slice(0, 2000),
  className: right.className
});

// Find all sidebar panels and their content
const all = document.querySelectorAll('.caption-card, .right-card, .info-card, [class*=sidebar], [class*=panel]');
const out = [];
for (const el of all) {
  const r = el.getBoundingClientRect();
  if (r.width === 0) continue;
  out.push({
    cls: el.className.slice(0, 60),
    x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
    text: el.innerText.slice(0, 200)
  });
}
return JSON.stringify(out);

// Find ALL sidebar-card elements (not just .caption-card)
const all = document.querySelectorAll('.sidebar-card, .right-button, [class*=npc], [class*=character]');
const out = [];
for (const el of all) {
  const r = el.getBoundingClientRect();
  out.push({
    cls: el.className.slice(0, 60),
    y: Math.round(r.y),
    text: el.innerText.slice(0, 250).replace(/\n+/g,' | ')
  });
}
return JSON.stringify(out);

