return JSON.stringify({
  time: SugarCube.State.variables.game.time,
  day: SugarCube.State.variables.game.day,
  energy: SugarCube.State.variables.player.energy,
  intelligence: SugarCube.State.variables.player.intelligence,
  npcLocations: {
    Dad: typeof GetNpcLocation === 'function' ? GetNpcLocation('Dad') : 'no fn',
    Brother: typeof GetNpcLocation === 'function' ? GetNpcLocation('Brother') : 'no fn',
    Grandpa: typeof GetNpcLocation === 'function' ? GetNpcLocation('Grandpa') : 'no fn'
  }
});

// Inspect the game's NPC schedule data
const npcs = SugarCube.State.variables.npc;
const out = {};
if (npcs) {
  for (const k of Object.keys(npcs)) {
    const n = npcs[k];
    if (n && typeof n === 'object') {
      out[k] = {
        relation: n.relation,
        relationship: n.relationship,
        love: n.love,
        scheduleKeys: n.schedule ? Object.keys(n.schedule).slice(0,5) : null
      };
    }
  }
}
return JSON.stringify({npcs: out, gameTimeOptions: SugarCube.State.variables['%%cycles']});

// Now get the actual location field for Dad/Brother/Grandpa
const out = {};
for (const k of ['Dad','Brother','Grandpa','Marcus','Natasha']) {
  const n = SugarCube.State.variables.npc[k];
  if (n) {
    out[k] = {
      location: n.location,
      keys: Object.keys(n).filter(x => !['scenes','statistics'].includes(x)).slice(0, 20)
    };
  }
}
return JSON.stringify(out);

return JSON.stringify({
  time: SugarCube.State.variables.game.time,
  day: SugarCube.State.variables.game.day,
  energy: SugarCube.State.variables.player.energy,
  intelligence: SugarCube.State.variables.player.intelligence,
  npcs: {
    Dad: SugarCube.State.variables.npc.Dad.location,
    Brother: SugarCube.State.variables.npc.Brother.location,
    Grandpa: SugarCube.State.variables.npc.Grandpa.location,
    Marcus: SugarCube.State.variables.npc.Marcus.location,
    Natasha: SugarCube.State.variables.npc.Natasha.location
  }
});

// AddTime is a SugarCube macro - find the underlying function
const macros = SugarCube.Macro.has ? null : null;
// Try to find via setup
const cycle = SugarCube.State.variables['%%cycles'];
return JSON.stringify({
  cycles: cycle ? Object.keys(cycle) : 'none',
  cycleData: cycle,
  // Check for any time advance helper
  funcs: typeof AddTime !== 'undefined' ? AddTime.toString().slice(0, 600) : 'no AddTime fn'
});

const cycles = SugarCube.State.variables['%%cycles'];
return JSON.stringify({
  timeStack: cycles.time.stack,
  timePhase: cycles.time.phases[Math.floor(cycles.time.stack / cycles.time.period) % cycles.time.phases.length],
  dayStack: cycles.day.stack,
  hour: SugarCube.State.variables.game ? SugarCube.State.variables.game.hour : 'no'
});

const c = SugarCube.State.variables['%%cycles'];
const t = c.time;
const d = c.day;
return JSON.stringify({
  time_stack: t && t.stack,
  time_period: t && t.period,
  time_phases: t && t.phases,
  day_stack: d && d.stack,
  current_phase_index: t ? Math.floor(t.stack / t.period) % t.phases.length : 'none',
  current_phase: t ? t.phases[Math.floor(t.stack / t.period) % t.phases.length] : 'none'
});

// Force-advance time by calling AddTime macro N times
const macro = SugarCube.Macro.get('AddTime');
if (macro) {
  // Run the AddTime side effect manually 6 times
  for (let i=0; i<6; i++) {
    const div = document.createElement('div');
    div.innerHTML = '<<AddTime 2>>';
    SugarCube.Wikifier.wikifyEval('<<AddTime 2>>');
  }
}
return JSON.stringify({
  time: SugarCube.State.variables.game.time,
  day: SugarCube.State.variables.game.day,
  npcs: {
    Dad: SugarCube.State.variables.npc.Dad.location,
    Brother: SugarCube.State.variables.npc.Brother.location,
    Grandpa: SugarCube.State.variables.npc.Grandpa.location
  }
});

// Find AddTime, ChangeTime functions in setup namespace
const ns = window.setup;
const keys = ns ? Object.keys(ns).filter(k => /time|cycle|schedule|npc|location/i.test(k)) : [];
return JSON.stringify({setup_keys: keys.slice(0,40)});

