// Find isBoyfriend, Talk macro definitions
const out = {};
if (typeof isBoyfriend === 'function') {
  out.isBoyfriend = isBoyfriend.toString().slice(0, 800);
}
// SugarCube macros are stored in SugarCube.Macro
