if (talkMacro) {
  out.Talk = (talkMacro.handler || talkMacro.tags || 'no-handler').toString().slice(0, 1500);
}
return JSON.stringify(out);

const out = {};
if (typeof NpcService !== 'undefined') {
  out.npcTalk = NpcService.npcTalk ? NpcService.npcTalk.toString().slice(0, 1500) : 'no fn';
  out.NpcService_keys = Object.keys(NpcService).slice(0, 20);
}
if (typeof PlayerService !== 'undefined') {
  out.isBoyfriend_impl = PlayerService.isBoyfriend ? PlayerService.isBoyfriend.toString().slice(0, 800) : 'no';
  out.PlayerService_keys = Object.keys(PlayerService).slice(0, 30);
}
return JSON.stringify(out);

